import { readFileSync } from 'node:fs';
import { PGlite } from '@electric-sql/pglite';
import { PGLiteSocketServer } from '@electric-sql/pglite-socket';
import { Sequelize, DataTypes, Op, fn, col, literal } from 'sequelize';
import { Umzug, SequelizeStorage } from 'umzug';
import { Kysely, PostgresDialect, sql } from 'kysely';
import pg from 'pg';

// PGlite in-process, exposed over the Postgres wire protocol so stock drivers can talk to it
const db = await PGlite.create();
const server = new PGLiteSocketServer({ db, port: 0, host: '127.0.0.1' });
await server.start();
const port = server.server?.address?.().port ?? server.port;
console.log('socket port:', port);
const url = `postgres://postgres:postgres@127.0.0.1:${port}/postgres`;

// --- Sequelize over the socket, pool of exactly one connection
const sequelize = new Sequelize(url, { dialect: 'postgres', logging: false, pool: { max: 1, min: 0 } });
await sequelize.authenticate();
console.log('sequelize authenticate: ok');

// Umzug (the runner sequelize-cli uses) resolving plain .sql files
const umzug = new Umzug({
  migrations: { glob: 'migrations/*.sql', resolve: ({ name, path }) => ({
    name, up: async () => sequelize.query(readFileSync(path, 'utf8')) }) },
  storage: new SequelizeStorage({ sequelize }), logger: undefined,
});
console.log('umzug ran:', (await umzug.up()).map(m => m.name));

const Task = sequelize.define('Task', {
  id: { type: DataTypes.INTEGER, primaryKey: true },
  orgId: { type: DataTypes.INTEGER, field: 'org_id' },
  status: DataTypes.TEXT,
  dueDate: { type: DataTypes.DATEONLY, field: 'due_date' },
  deletedAt: { type: DataTypes.DATE, field: 'deleted_at' },
}, { tableName: 'task', timestamps: false });

// Per-request tenant context: transaction-local GUC + role, then ORM queries inside it
const asTenant = (orgId, work) => sequelize.transaction(async (t) => {
  await sequelize.query(`select set_config('app.org_id', :orgId, true)`, { replacements: { orgId: String(orgId) }, transaction: t });
  await sequelize.query('set local role app_user', { transaction: t });
  return work(t);
});

await asTenant(1, async (t) => {
  console.log('RLS rows visible to org 1:', await Task.count({ transaction: t }));
  // keyset page 2: (due_date, id) > cursor, must drop to literal for the row comparison
  const page = await Task.findAll({
    where: { deletedAt: null, [Op.and]: [literal(`(due_date, id) > ('2026-11-05', 10)`)] },
    order: [['dueDate', 'ASC'], ['id', 'ASC']], limit: 3, transaction: t,
  });
  console.log('keyset page:', page.map(r => `${r.dueDate}#${r.id}`).join(', '));
  const viaCount = await Task.count({ group: ['status'], transaction: t });
  console.log('Task.count({group}) ->', JSON.stringify(viaCount));
  const viaFn = await Task.findAll({ attributes: ['status', [fn('count', col('id')), 'n']], group: ['status'], raw: true, transaction: t });
  console.log('findAll fn(count) ->', JSON.stringify(viaFn), 'typeof n:', typeof viaFn[0].n);
});
console.log('session role after tx:', (await sequelize.query('select current_user', { plain: true })).current_user);
await sequelize.close();

// --- Kysely with the stock PostgresDialect over the same socket (no PGlite-specific dialect)
const kdb = new Kysely({ dialect: new PostgresDialect({ pool: new pg.Pool({ connectionString: url, max: 1 }) }) });
const rows = await kdb.transaction().execute(async (trx) => {
  await sql`select set_config('app.org_id', ${'2'}, true)`.execute(trx);
  await sql`set local role app_user`.execute(trx);
  return trx.selectFrom('task').select(['status', (eb) => eb.fn.countAll().as('n')]).groupBy('status').execute();
});
console.log('kysely org 2 by status:', JSON.stringify(rows), 'typeof n:', typeof rows[0].n);
await kdb.destroy();
await server.stop(); await db.close();
EOF
